def list_value_options(df: pd.DataFrame) -> dict:
    """Return sorted unique options for selectors."""
    return {
        "countries": sorted(df["REF_AREA"].dropna().unique().tolist()),
        "products": sorted(df["ENERGY_PRODUCT"].dropna().unique().tolist()),
