    mom = calculate_mom_percent(raw)
    mom_ch = calculate_mom_change(raw)
    yoy = calculate_yoy_percent(raw)
    yoy_ch = calculate_yoy_change(raw)

    JODI_DATA = {
        "raw_data": raw,
        "mom_data": mom,
        "mom_change": mom_ch,
        "yoy_data": yoy,
        "yoy_change": yoy_ch,
