def build_data_dict_from_raw(raw_df: pd.DataFrame, rename_map: dict[str, str] | None = None) -> dict[str, Any]:
    if raw_df is None or raw_df.empty:
        return {}
    raw = raw_df.sort_index().rename(columns=lambda c: rename_map.get(c, c) if rename_map else c)
    raw = raw.apply(pd.to_numeric, errors="ignore")
    raw = raw.dropna(how="all")
    return {
        "raw_data": raw,
        "mom_data": calculate_mom_percent(raw),
        "mom_change": calculate_mom_change(raw),
        "yoy_data": calculate_yoy_percent(raw),
        "yoy_change": calculate_yoy_change(raw),
        "load_info": {
            "loaded": True,
            "load_time": datetime.now(),
            "start_date": raw.index.min().strftime("%Y-%m-%d"),
            "series_count": raw.shape[1],
            "data_points": raw.shape[0],
            "source": "CSV (cache)",
        },
    }


def _sanitize_plotly_figure(fig):
    if fig is None or not hasattr(fig, "layout"):
        return fig

    if hasattr(fig.layout, "title"):
        text = getattr(fig.layout.title, "text", None)
        if text is None or str(text).strip().lower() == "undefined":
            fig.layout.title.text = ""

    for axis_name in ("yaxis", "yaxis2"):
        axis = getattr(fig.layout, axis_name, None)
        if axis is not None and hasattr(axis, "title"):
            text = getattr(axis.title, "text", None)
            if text is None or str(text).strip().lower() == "undefined":
                axis.title.text = ""

    annotations = []
    for ann in getattr(fig.layout, "annotations", []):
        text = getattr(ann, "text", None)
        if text is None or str(text).strip().lower() != "undefined":
            annotations.append(ann)
    if annotations or getattr(fig.layout, "annotations", None):
        fig.update_layout(annotations=annotations)
    return fig


def _normalize_series(series: pd.Series) -> pd.Series:
    s = pd.to_numeric(series, errors="coerce")
    return s.dropna()


def _make_monthly_five_year_format(series: pd.Series, history_years: int = 5) -> pd.DataFrame | None:
    monthly = _normalize_series(series)
    if monthly.empty:
        return None
    monthly.index = pd.to_datetime(monthly.index)
    monthly = monthly[~monthly.index.duplicated(keep="last")].sort_index()
